import { test, expect } from '@playwright/test';
import { prepareReadOnly, openCalculator, fillInputs, expectResult, SET1, DEVICES } from './calculator.helpers';

test.use({ serviceWorkers: 'block' });

test.describe('Калькулятор — формулы и крайние случаи', () => {
  for (const tag of DEVICES) {
    test(`Набор 1: все результаты по формулам, пересчёт без кнопки #80ff63 #22ce3e #d45b2a ${tag} @prod-safe`, async ({ page, context }) => {
      await prepareReadOnly(context);
      await openCalculator(page);
      await fillInputs(page, SET1);

      await expectResult(page, 'סך השקעה ראשונית', '600,000 ₪');
      await expectResult(page, 'הון עצמי נדרש', '400,000 ₪');
      await expectResult(page, 'מס חודשי משוער', '5,750 ₪');
      await expectResult(page, 'רווח חודשי לאחר מס', '19,250 ₪');
      await expectResult(page, 'תזרים חודשי משוער', '14,250 ₪');
      await expect(page.getByText(/^בשנה:/)).toHaveText(/בשנה:\s*‏?171,000\s*‏?₪/);
      await expectResult(page, 'תשואה שנתית על ההון העצמי', '42.8%');
      await expectResult(page, 'תשואה שנתית על ההשקעה הכוללת', '38.5%');
      await expectResult(page, 'זמן החזר ההון העצמי', 'שנתיים ו־5 חודשים');
    });
  }
});
